sys_script.script:
(function executeRule(current, previous /*null when async*/) {

    var utils = new x_783736_time_tr_0.TimeTrackerUtils();

    // When a record is deleted, "current" can be empty, so we fall back to "previous"
    var empId = current.getValue('employee') || (previous && previous.getValue('employee'));
    var workDate = current.getValue('work_date') || (previous && previous.getValue('work_date'));

    // 1. Recalculate Under / On / Over Target status for all entries on this user + date
    utils.recalculateDailyStatus(empId, workDate);

    // 2. Roll up total dollar spend onto the parent Approved Project record
    var projId = current.getValue('project') || (previous && previous.getValue('project'));
    if (projId) {
        var totalSpend = 0;

        // GlideAggregate lets the database sum up numbers directly (much faster than looping every row!)
        var ga = new GlideAggregate('x_783736_time_tr_0_time_entry');
        ga.addQuery('project', projId);           // Filter to this specific project
        ga.addAggregate('SUM', 'calculated_cost'); // Ask DB to sum the calculated_cost column
        ga.query();

        if (ga.next()) {
            totalSpend = parseFloat(ga.getAggregate('SUM', 'calculated_cost')) || 0;
        }

        // Open the Approved Project record and update its Total Cost Spent field
        var projGr = new GlideRecord('x_783736_time_tr_0_approved_project');
        if (projGr.get(projId)) {
            projGr.setValue('total_cost_spent', totalSpend);
            projGr.update();
        }
    }

})(current, previous);
